import{_ as n,o as t,c as i,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const r="/bilder/unterricht-kataloge/kataloge-schulbez-abteilungen-1.png",u="/bilder/unterricht-kataloge/kataloge-schulbez-abteilungen-2.png",b=JSON.parse('{"title":"Abteilungen und Klassengruppen einrichten","description":"","frontmatter":{"title":"Abteilungen und Klassengruppen einrichten","source_pageid":459,"source_revision":5428},"headers":[],"relativePath":"schild3/unterricht-kataloge/klassengruppen-abteilungen-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/klassengruppen-abteilungen-schulbezogene-kataloge.md"}'),l={name:"schild3/unterricht-kataloge/klassengruppen-abteilungen-schulbezogene-kataloge.md"};function s(o,e,g,d,p,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="abteilungen-und-klassengruppen-einrichten" tabindex="-1">Abteilungen und Klassengruppen einrichten <a class="header-anchor" href="#abteilungen-und-klassengruppen-einrichten" aria-label="Permalink to &quot;Abteilungen und Klassengruppen einrichten&quot;">​</a></h1><p>Fassen Sie Klassen zu Abteilungen zusammen und hinterlegen Sie die zuständige Koordination mit ihren Kontaktdaten.</p><p><a href="/bilder/unterricht-kataloge/kataloge-schulbez-abteilungen-1.png"><img src="'+r+'" alt="Abteilungen und Koordinatoren festlegen." loading="lazy"></a></p><p><em>Abteilungen und Koordinatoren festlegen.</em></p><p>Sie können Abteilungen und Koordinatoren definieren, die für bestimmte Klassen oder Jahrgangsstufen zuständig sind. Dies kann nützlich sein, um diese Abteilungsleitungen bzw. Koordinatoren dann über die Benutzerverwaltung mit passenden Rechten auszustatten.</p><p>Außerdem können diese Abteilungsleitungen bzw. Koordinatoren über einen Report aufgerufen werden, um die Verantwortlichen und ihre gesetzten Kontaktdaten automatisch basierend auf einer im Report verarbeiteten Klassen im Report einzubinden, zum Beispiel &quot;Auskunft erteilt Mustermann, Durchwahl -032&quot;.</p><p>Legen Sie zuerst wie in SchILD üblich mit dem &quot;<strong>+</strong>&quot; eine Abteilung an, die sie nun benennen können. Fügen Sie eine <em>koordinierende Person</em> hinzu und bei Wunsch auch den <em>Raum</em>, die <em>Durchwahl</em> und eine <em>E-Mail</em>-Adresse.</p><p><a href="/bilder/unterricht-kataloge/kataloge-schulbez-abteilungen-2.png"><img src="'+u+'" alt="Klassen zu einer Abteilung/Koordination hinzufügen." loading="lazy"></a></p><p><em>Klassen zu einer Abteilung/Koordination hinzufügen.</em></p><p>Klicken Sie dann auf das kleine &quot;<strong>+</strong>&quot; vor der Abteilung und fügen Sie Klassen zu dieser hinzu. Diese sind ab nun mit der Abteilung verbunden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Klassengruppen/Abteilungen_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5428.</p>',12)])])}const m=n(l,[["render",s]]);export{b as __pageData,m as default};
